function pickBestXi(squad, gwIdx) {
  const xpMap = {};
  squad.forEach(p => { xpMap[p.id] = _xpAt(p, gwIdx); });

  const formations = [
     
     
     
    [1,3,4,3], [1,3,5,2], [1,4,3,3], [1,4,4,2], [1,5,3,2], [1,4,5,1], [1,5,4,1], [1,5,2,3]
  ];

  let bestXi = [];
  let bestScore = -Infinity;

   
   
   
   
   
  const byPos = {1: [], 2: [], 3: [], 4: []};
  squad.forEach(p => {
    if (!byPos[p.element_type]) byPos[p.element_type] = [];
    byPos[p.element_type].push(p);
  });
  Object.keys(byPos).forEach(pos => {
     
    byPos[pos].sort((a, b) => (xpMap[b.id] - xpMap[a.id]) || ((+a.id || 0) - (+b.id || 0)));
  });

   
   
  let bestForm = null;
  formations.forEach(form => {
    for (let q = 0; q < 4; q++) if ((byPos[q + 1] || []).length < form[q]) return;    
    let score = 0;
    for (let q = 0; q < 4; q++) {
      const arr = byPos[q + 1];
      for (let j = 0; j < form[q]; j++) score += xpMap[arr[j].id];
    }
    if (score > bestScore) { bestScore = score; bestForm = form; }
  });
  if (bestForm) {
    for (let q = 0; q < 4; q++) for (let j = 0; j < bestForm[q]; j++) bestXi.push(byPos[q + 1][j]);
  }

  if (bestXi.length === 0) bestXi = squad.slice(0, 11);

   
   
   
   
   
   
   
  const _before = (a, b) => {
    const d = xpMap[b.id] - xpMap[a.id];
    return d !== 0 ? d < 0 : ((a.id || 0) - (b.id || 0)) < 0;
  };
  let cap = undefined, vc = undefined;
  for (const p of bestXi) {
    if (cap === undefined || _before(p, cap)) { vc = cap; cap = p; }
    else if (vc === undefined || _before(p, vc)) vc = p;
  }
  if (vc === undefined) vc = cap;

  const xiIds = new Set(bestXi.map(p => p.id));
  const bench = squad.filter(p => !xiIds.has(p.id));

  return { xi: bestXi, bench, cap, vc };
}

 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
