const _CHIP_LABELS = { wc:'WC', bb:'BB', tc:'TC', fh:'FH' };
const _CHIP_CLS    = { wc:'pct-wc', bb:'pct-bb', tc:'pct-tc', fh:'pct-fh' };

function updatePillChipTags() {
  const chipGws = {};
  ['wc','bb','tc','fh'].forEach(c => {
    const v = parseInt(document.getElementById(`sel-${c}`)?.value || 0);
    if (v) chipGws[v] = chipGws[v] ? [...chipGws[v], c] : [c];
  });
  document.querySelectorAll('.gw-pill').forEach(btn => {
     
    btn.querySelectorAll('.pill-chip-tag').forEach(t => t.remove());
    const gw = parseInt(btn.dataset.gw);
    const chips = chipGws[gw] || [];
    chips.forEach(c => {
      const tag = document.createElement('span');
      tag.className = `pill-chip-tag ${_CHIP_CLS[c]}`;
      tag.textContent = _CHIP_LABELS[c];
      btn.appendChild(tag);
    });
  });
}

 
 
 
 
 
 
 
 
 
 
 
 
 
 
window._PROJECTION_SOURCE = 'apex';
window._APEX_XP_CACHE = null;   

function _cacheApexXp() {
  if (window._APEX_XP_CACHE) return;
  const cache = {};
   
  if (Array.isArray(POOL_DATA)) {
    POOL_DATA.forEach(function (p) {
      if (!p || p.id == null) return;
      cache[p.id] = {
        xp: p.xp,
        xp_per_gw: Array.isArray(p.xp_per_gw) ? p.xp_per_gw.slice() : null,
      };
    });
  }
   
  if (Array.isArray(SQUAD_DATA)) {
    SQUAD_DATA.forEach(function (p) {
      if (!p || p.id == null) return;
       
      if (!cache[p.id]) {
        cache[p.id] = {
          xp: p.xp,
          xp_per_gw: Array.isArray(p.xp_per_gw) ? p.xp_per_gw.slice() : null,
        };
      }
    });
  }
  window._APEX_XP_CACHE = cache;
}

function _applyXpFromSource(src) {
   
   
   
  if (src === 'compare') {
     
     
    const lookup = (typeof COMPARE_XP_LOOKUP === 'object' && COMPARE_XP_LOOKUP) ? COMPARE_XP_LOOKUP : {};
    const apply = function (arr) {
      if (!Array.isArray(arr)) return;
      arr.forEach(function (p) {
        if (!p || p.id == null) return;
        const rv = lookup[p.id];
        if (Array.isArray(rv) && rv.length > 0) {
          p.xp_per_gw = rv.slice();
          p.xp = Math.round(rv.reduce(function (s, x) { return s + (x || 0); }, 0) * 100) / 100;
        }
         
      });
    };
    apply(POOL_DATA);
    apply(SQUAD_DATA);
  } else {
     
    const cache = window._APEX_XP_CACHE || {};
    const restore = function (arr) {
      if (!Array.isArray(arr)) return;
      arr.forEach(function (p) {
        if (!p || p.id == null) return;
        const c = cache[p.id];
        if (c) {
          p.xp = c.xp;
          if (c.xp_per_gw) p.xp_per_gw = c.xp_per_gw.slice();
        }
      });
    };
    restore(POOL_DATA);
    restore(SQUAD_DATA);
  }
}

function _swapKeyedSquadMap(targetMap, sourceMap) {
   
   
   
  if (!targetMap || !sourceMap) return;
  Object.keys(targetMap).forEach(function (k) { delete targetMap[k]; });
  Object.keys(sourceMap).forEach(function (k) {
    targetMap[k] = JSON.parse(JSON.stringify(sourceMap[k]));
  });
}

function _recomputeGwBaselinesFromSquad() {
   
   
   
  if (!window.ApexSolver || typeof window.ApexSolver.pickOptimalXI !== 'function') {
    console.warn('[compare-toggle] ApexSolver.pickOptimalXI unavailable — totals will not refresh');
    return;
  }
  if (!Array.isArray(SQUAD_DATA) || !Array.isArray(GW_XI_BASE)) return;
  for (let i = 0; i < GW_XI_BASE.length; i++) {
    try {
      const r = window.ApexSolver.pickOptimalXI(SQUAD_DATA, i);
      const xiSum = (r && typeof r.xi_xp === 'number') ? r.xi_xp : 0;
      const totalXp = (r && typeof r.total_xp === 'number') ? r.total_xp : xiSum;
       
      const capDouble = Math.max(0, totalXp - xiSum);
      GW_XI_BASE[i] = xiSum;
      GW_CAP_XP[i] = capDouble;
       
      if (typeof GW_BENCH !== 'undefined' && Array.isArray(GW_BENCH)) {
        let benchXp = 0;
        if (r && Array.isArray(r.bench)) {
          r.bench.forEach(function (p) {
            const xpg = (p && Array.isArray(p.xp_per_gw)) ? (p.xp_per_gw[i] || 0) : 0;
            benchXp += xpg;
          });
        }
        GW_BENCH[i] = Math.round(benchXp * 100) / 100;
      }
    } catch (_e) {
       
    }
  }
   
  if (typeof _xiDelta !== 'undefined' && Array.isArray(_xiDelta)) {
    for (let i = 0; i < _xiDelta.length; i++) _xiDelta[i] = 0;
  }
  if (typeof _capDelta !== 'undefined' && Array.isArray(_capDelta)) {
    for (let i = 0; i < _capDelta.length; i++) _capDelta[i] = 0;
  }
  if (typeof _benchDelta !== 'undefined' && Array.isArray(_benchDelta)) {
    for (let i = 0; i < _benchDelta.length; i++) _benchDelta[i] = 0;
  }
   
  if (typeof _gwTotals !== 'undefined' && Array.isArray(_gwTotals)) {
    for (let i = 0; i < _gwTotals.length; i++) {
      _gwTotals[i] = (GW_XI_BASE[i] || 0) + (GW_CAP_XP[i] || 0);
    }
  }
}

function _setProjectionSource(src) {
  if (src !== 'apex' && src !== 'compare') return;
  if (window._PROJECTION_SOURCE === src) return;
  _cacheApexXp();
  window._PROJECTION_SOURCE = src;
  _applyXpFromSource(src);
   
   
  _recomputeGwBaselinesFromSquad();
   
  try {
    if (typeof updateChipTotal === 'function') updateChipTotal();
    else if (typeof updateRollingTotal === 'function') updateRollingTotal();
  } catch (_e) {}
   
   
   
   
   
   
  try {
    if (src === 'compare') {
       
      if (!window._APEX_WC_SQUADS_BACKUP_LIVE && typeof WC_SQUADS !== 'undefined') {
        window._APEX_WC_SQUADS_BACKUP_LIVE = JSON.parse(JSON.stringify(WC_SQUADS));
      }
      if (!window._APEX_FH_SQUADS_BACKUP_LIVE && typeof FH_SQUADS !== 'undefined') {
        window._APEX_FH_SQUADS_BACKUP_LIVE = JSON.parse(JSON.stringify(FH_SQUADS));
      }
      const rwc = (typeof COMPARE_WC_SQUADS === 'object') ? COMPARE_WC_SQUADS : null;
      const rfh = (typeof COMPARE_FH_SQUADS === 'object') ? COMPARE_FH_SQUADS : null;
      if (rwc && Object.keys(rwc).length > 0 && typeof WC_SQUADS !== 'undefined') {
        _swapKeyedSquadMap(WC_SQUADS, rwc);
      }
      if (rfh && Object.keys(rfh).length > 0 && typeof FH_SQUADS !== 'undefined') {
        _swapKeyedSquadMap(FH_SQUADS, rfh);
      }
    } else {
       
       
       
      const wcRestore = window._APEX_WC_SQUADS_BACKUP_LIVE
        || (typeof _APEX_WC_SQUADS_BACKUP === 'object' ? _APEX_WC_SQUADS_BACKUP : null);
      const fhRestore = window._APEX_FH_SQUADS_BACKUP_LIVE
        || (typeof _APEX_FH_SQUADS_BACKUP === 'object' ? _APEX_FH_SQUADS_BACKUP : null);
      if (wcRestore && typeof WC_SQUADS !== 'undefined') {
        _swapKeyedSquadMap(WC_SQUADS, wcRestore);
      }
      if (fhRestore && typeof FH_SQUADS !== 'undefined') {
        _swapKeyedSquadMap(FH_SQUADS, fhRestore);
      }
    }
  } catch (_e) {
    console.warn('[compare-toggle] FH/WC swap hiccup:', _e);
  }
   
  const btnA = document.getElementById('va-toggle-apex');
  const btnR = document.getElementById('va-toggle-compare');
  if (btnA && btnR) {
    btnA.classList.toggle('va-toggle-active', src === 'apex');
    btnR.classList.toggle('va-toggle-active', src === 'compare');
  }
   
  document.body.classList.toggle('compare-alt', src === 'compare');
  document.body.classList.toggle('compare-apex',   src === 'apex');
   
   
   
  try {
    if (typeof activeGwIdx === 'number') _renderHeroSparkline();
    if (typeof initTeamView === 'function') initTeamView();
    if (typeof renderPool === 'function') renderPool();
  } catch (_e) {
    console.warn('[compare-toggle] re-render hiccup:', _e);
  }
  console.log('[compare-toggle] projection source =', src);
}

 
 
 
 
window._setProjectionSource = _setProjectionSource;

function _initCompareToggle() {
   
   
   
   
   
   
  try {
    const params = new URLSearchParams(window.location.search);
    const cv = params.get('compare');
    if (cv === 'enable') {
      try { localStorage.setItem('apex_dev', '1'); } catch (_) {}
      params.set('compare', '1');
      const newUrl = window.location.pathname + '?' + params.toString() + window.location.hash;
      window.location.replace(newUrl);
      return;
    }
    if (cv === 'disable') {
      try { localStorage.removeItem('apex_dev'); } catch (_) {}
      params.delete('compare');
      const q = params.toString();
      const newUrl = window.location.pathname + (q ? '?' + q : '') + window.location.hash;
      window.location.replace(newUrl);
      return;
    }
    const urlOk = (cv === '1');
    const lsOk = (function () {
      try { return localStorage.getItem('apex_dev') === '1'; } catch (_) { return false; }
    })();
    if (urlOk && lsOk) {
      const cell = document.getElementById('va-compare-toggle');
      if (cell) cell.style.display = '';
    }
  } catch (_e) {}
}

 
 
 
 
 
 
 
 
 
 
 
