    if (!board || !pitchCol) return;
    if (pitchCol.clientWidth < 200) return;  
    function set(svg) { root.style.setProperty('--apex-shirt', svg + 'px'); root.style.setProperty('--apex-shirt-w', (svg * 1.46) + 'px'); }
    if (tabs) {   }
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
    var _slotRows = [];
    var _rowEls = board.querySelectorAll('.pitch-row');
    for (var _ri = 0; _ri < _rowEls.length; _ri++) _slotRows.push(_rowEls[_ri].children.length);
    var _benchRowEl = document.querySelector('.va-twopane-pitch .bench-row, .va-twopane-pitch .pitch-bench');
    _slotRows.push(_benchRowEl ? _benchRowEl.children.length : 4);
    var _widest = 4;
    for (var _si = 0; _si < _slotRows.length; _si++) {
      if (_slotRows[_si] > _widest) _widest = _slotRows[_si];
    }
     
    if (typeof window.APEX_KIT_ROWS === 'number' && window.APEX_KIT_ROWS >= 3) {
      _widest = window.APEX_KIT_ROWS;
    }
    var target = ((pitchCol.clientWidth / _widest) - 8) / 1.46;
    target = Math.min(target, 150);
     
     
     
     
     
     
     
     
     
     
    var _kitMax = (typeof window.APEX_KIT_MAX === 'number' && window.APEX_KIT_MAX > 0)
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                   
                  ? window.APEX_KIT_MAX : 92;
    target = Math.min(target, _kitMax);
    target = Math.max(target, 40);
    set(target);
    var benchEl = document.querySelector('.va-twopane-pitch .bench-row, .va-twopane-pitch .pitch-bench') || board;
    var _cont = document.querySelector('.container');
    var _clip = _cont ? _cont.getBoundingClientRect().bottom : window.innerHeight;
     
     
     
     
     
    var _extraNS = (typeof window.APEX_FIT_EXTRA === 'number' && window.APEX_FIT_EXTRA > 0)
                   ? window.APEX_FIT_EXTRA : 0;
