function _apexChipSet2Note() {
  try {
    const host = document.getElementById('chip-set2-note');
    if (!host) return;
    const SET1_LAST = 19, SET2_FIRST = 20;
    const gwr = (typeof TEAM_META !== 'undefined' && TEAM_META && Array.isArray(TEAM_META.gw_range))
      ? TEAM_META.gw_range : [];
    if (!gwr.length) { host.innerHTML = ''; return; }
    const startGw = +gwr[0];
     
     
     
     
     
     
     
     
     
    const lastGw = +gwr[gwr.length - 1];
     
     
    if (startGw > SET1_LAST || lastGw < SET1_LAST) { host.innerHTML = ''; return; }
     
     
     
    const showsBlanks = lastGw > SET1_LAST;
    const left = Math.max(0, SET1_LAST - startGw + 1);
    host.innerHTML =
      '<div style="margin:10px 0 2px;padding:10px 12px;border:1px solid #E8B54A;'
      + 'border-radius:10px;background:#FFF9EC;font-size:.78rem;line-height:1.5;'
      + 'color:#5C4708;">'
      + '<strong>Heads-up — your first chip set expires at GW' + SET1_LAST + '.</strong> '
      + (left > 0
          ? ('You have ' + left + ' gameweek' + (left === 1 ? '' : 's') + ' left to use anything unplayed; it does not carry over. ')
          : '')
      + (showsBlanks
          ? ('Weeks from GW' + SET2_FIRST + ' are left blank on purpose: the second set '
             + 'unlocks then, and Apex does not plan those yet — so treat a blank week as '
             + '"not modelled", not "not worth it".')
          : ('The second set unlocks at GW' + SET2_FIRST + ', and Apex does not plan those '
             + 'weeks yet — nothing here is a verdict on them.'))
      + '</div>';
  } catch (_e) {   }
}

 
 
 
 
 
 
 
 
function _apexChipUnavailableNote() {
  try {
    const host = document.getElementById('chip-unavailable-note');
    if (!host) return;
    const cu = (typeof CHIP_PLANNER !== 'undefined' && CHIP_PLANNER
                && CHIP_PLANNER.chip_unavailable) || {};
    const parts = [];
    [['wc', 'Wildcard'], ['fh', 'Free Hit']].forEach(function (pair) {
      const gws = Array.isArray(cu[pair[0]]) ? cu[pair[0]] : [];
      if (gws.length) parts.push(pair[1] + ' \u2014 GW' + gws.join(', GW'));
    });
    if (!parts.length) { host.innerHTML = ''; return; }
    host.innerHTML =
      '<div style="margin:10px 0 2px;padding:10px 12px;border:1px solid #E8B54A;'
      + 'border-radius:10px;background:#FFF9EC;font-size:.78rem;line-height:1.5;'
      + 'color:#5C4708;">'
      + '<strong>Some weeks could not be priced.</strong> '
      + parts.join(' &middot; ')
      + '. The squad solver could not build a legal chip squad for those '
      + 'gameweeks, so they are left blank rather than guessed \u2014 read a '
      + 'blank there as "not solvable", not "not worth it".'
      + '</div>';
  } catch (_e) {   }
}

function _apexBuildHorizonPicker() {
  try {
     
     
     
     
     
     
     
    const host = document.getElementById('va-solve-actions')
              || document.querySelector('nav.nav');
    const inNav = !document.getElementById('va-solve-actions');
    if (!host || document.getElementById('apex-hz-pick')) return;
    const allowed = +(window.__APEX_HZ_ALLOWED || 0);
    const pick    = +(window.__APEX_HZ_PICK || allowed);
     
    if (!(allowed > 1)) return;

    const wrap = document.createElement('span');
    wrap.className = 'apex-hz-wrap';
     
     
     
     
     
    wrap.style.cssText = 'display:inline-flex;align-items:center;align-self:center;'
      + 'gap:6px;line-height:1;'
      + (inNav ? 'margin-left:auto;padding:5px 10px;' : 'padding:10px 14px;')
      + 'border:1px solid var(--border,#DCE2DE);border-radius:9px;'
      + 'background:var(--bg2,#fff);';
    const sel = document.createElement('select');
    sel.id = 'apex-hz-pick';
    sel.setAttribute('aria-label', 'Planning horizon in gameweeks');
    sel.style.cssText = 'border:none;background:transparent;font-family:inherit;'
      + 'font-size:.78rem;font-weight:800;color:var(--text,#0E1B16);cursor:pointer;outline:none;';
    for (let n = 1; n <= allowed; n++) {
      const o = document.createElement('option');
      o.value = String(n);
      o.textContent = n + (n === 1 ? ' GW' : ' GWs');
      if (n === pick) o.selected = true;
      sel.appendChild(o);
    }
     
    const bakeMax = +(window.__APEX_HZ_MAX || allowed);
    wrap.title = (allowed < bakeMax)
      ? ('Planning horizon. Your plan allows up to ' + allowed + ' gameweeks; '
         + bakeMax + ' are available on the season pass.')
      : ('How many gameweeks to plan ahead (up to ' + allowed + ').');
    sel.onchange = function () {
      const v = Math.max(1, Math.min(parseInt(sel.value, 10) || 1, allowed));
      try { localStorage.setItem('apex_horizon_v1', String(v)); } catch (_e) {}
      try { if (typeof _apexUse === 'function') _apexUse('horizon'); } catch (_eUse) {}    
      location.reload();
    };
    const cal = document.createElement('span');
    cal.textContent = '';    
    cal.setAttribute('aria-hidden', 'true');
    cal.style.cssText = 'font-size:.8rem;opacity:.65;';
    wrap.appendChild(cal);
     
     
    if (!inNav) {
      const lab = document.createElement('span');
      lab.textContent = 'Horizon';
      lab.style.cssText = 'font-size:.7rem;font-weight:800;letter-spacing:.04em;'
        + 'text-transform:uppercase;color:var(--muted,#5F6B65);';
      wrap.appendChild(lab);
    }
    wrap.appendChild(sel);
     
     
     
     
     
     
     
     
     
    try {
      const _cl = window.__APEX_HZ_CLAMPED;
      const _pc = window.__APEX_PLAN_HZ_CLAMPED;
      if ((_cl && _cl.saved > _cl.to) || (_pc && _pc.dropped > 0)) {
        wrap.title += (_cl
          ? ('  You had chosen ' + _cl.saved + ' gameweeks; projections go up to ' + (_cl.stated || _cl.to) + '.')
          : '')
          + (_pc && _pc.dropped > 0
             ? ('  ' + _pc.dropped + ' item(s) in your saved plan sat in gameweeks '
                + 'after GW' + _pc.lastGw + ' and were dropped, for the same reason.')
             : '');
      }
    } catch (_cE) {}
    host.appendChild(wrap);
  } catch (_e) {   }
}
 
 
 
