  try { if (typeof _apexApplyChipAvailability === 'function') _apexApplyChipAvailability(); } catch (_eAv) {}
  try { if (typeof _apexChipAdviceApply === 'function') _apexChipAdviceApply(); } catch (_eAd) {}

   
  const targetPill = document.querySelector(`.gw-pill[data-idx="${_prevActiveIdx}"]`)
                  || document.querySelector('.gw-pill');
  setBaseGw(targetPill);
