  const _preChipSq = _ppLedgerBuys([...(_xiPlayers || []), ...(_benchPlayers || [])], chipGwIdx);
  _pathPlanner.workingSquad     = _ppRebuildSquad(_preChipSq, chipSquad, 0).squad;
  _pathPlanner.rootSquad        = _ppCopySquad(_pathPlanner.workingSquad);
   
   
   
  _pathPlanner.rootPreChip      = (Array.isArray(_preChipSq) && _preChipSq.length === 15) ? _ppCopySquad(_preChipSq) : null;
  _pathPlanner.initialChipSquad = chipSquad.slice();   
   
   
   
   
   
   
   
   
   
   
   
   
