  const _crFtIn  = _crSeed ? _crSeed.ft
    : Math.max(0, _ppFtMeta() - _crPreTx);
  _pathPlanner.workingFt        = (chipType === 'WC' || chipType === 'FH')
    ? _ppFtAfterSquadChip(chipGwIdx, _crFtIn)    
    : _ppNextFt(chipGwIdx, _crFtIn, 0);           
  _pathPlanner.selections       = [];
  _pathPlanner.totalHits        = 0;
  _pathPlanner.restoredFromSaved = false;   

   
  const chipCost = chipSquad.reduce((s, p) => s + _ppEffCost(p), 0);
  const budgetCap = (TEAM_META && (TEAM_META.budget || ((TEAM_META.squad_value || 0) + (TEAM_META.bank || 0)))) || 0;
  const bankRaw = budgetCap - chipCost;
