function _ppRoundTrips() {
  try {
    const sels = (_pathPlanner && _pathPlanner.selections) || [];
    const HZ = (typeof APEX_TRANSFER_HORIZON === 'number') ? APEX_TRANSFER_HORIZON : 3;
    const DEC = (typeof APEX_TIME_DECAY === 'number') ? APEX_TIME_DECAY : 0.85;
    const xpAt = (p, i) => {
      try { return +((p && p.xp_per_gw) || [])[i] || 0; } catch (_e) { return 0; }
    };
    const outs = [];
    sels.forEach((s, si) => {
      [[s.out, s.in], [s.out2, s.in2]].forEach(pair => {
        if (pair[0] && pair[0].id != null) outs.push({ p: pair[0], repl: pair[1], si: si, gwIdx: s.gwIdx });
      });
    });
    const trips = [];
    sels.forEach((s, si) => {
      [s.in, s.in2].forEach(inP => {
        if (!inP || inP.id == null) return;
        const sold = outs.filter(o => o.p.id === inP.id && o.si < si)[0];
        if (!sold) return;
         
        let priced = 0;
        for (let k = 0; k < HZ; k++) {
          priced += Math.pow(DEC, k)
                  * (xpAt(sold.repl, sold.gwIdx + k) - xpAt(sold.p, sold.gwIdx + k));
        }
         
        let real = 0;
        for (let i = sold.gwIdx; i < s.gwIdx; i++) {
          real += Math.pow(DEC, i - sold.gwIdx)
                * (xpAt(sold.repl, i) - xpAt(sold.p, i));
        }
        trips.push({
          name: (inP.web_name || inP.name || '?'),
          soldGw: (TEAM_META && TEAM_META.gw_range ? TEAM_META.gw_range[sold.gwIdx] : sold.gwIdx + 1),
          backGw: (TEAM_META && TEAM_META.gw_range ? TEAM_META.gw_range[s.gwIdx] : s.gwIdx + 1),
          weeksAway: s.gwIdx - sold.gwIdx,
          replacedBy: (sold.repl && (sold.repl.web_name || sold.repl.name)) || '?',
          priced: Math.round(priced * 100) / 100,
          real: Math.round(real * 100) / 100,
          extraTransfers: 1
        });
      });
    });
    return trips;
  } catch (_e) { return []; }
}
