  const capXp = _capP ? _xpAt(_capP, gwIdx) : 0;

   
  _savedGwSquads[gwIdx] = {
    xi:    [...xi],
    bench: [...bench],
    capId, vcId,
    xiDelta:     xiSum - (GW_XI_BASE[gwIdx] || 0),
    capDelta:    capXp - (GW_CAP_XP[gwIdx]  || 0),
    jsBaseCapXp: capXp,
  };

   
  _xiDelta[gwIdx]    = _savedGwSquads[gwIdx].xiDelta;
  _capDelta[gwIdx]   = _savedGwSquads[gwIdx].capDelta;
  _benchDelta[gwIdx] = 0;

   
   
