    const label = (t) => `<span style="font-weight:800;color:var(--muted);">${t}</span>`;
    if (meta && Array.isArray(meta.moves) && meta.moves.length) {
      const shown = meta.moves.slice(0, 3);
      const more  = meta.moves.length - shown.length;
      let h = label('YOUR PLAN')
        + `<span style="color:var(--muted);">GW${meta.gwA}${(meta.gwB && +meta.gwB !== +meta.gwA) ? '–GW' + meta.gwB : ''}</span>`;
      for (const m of shown) {
        const mm = String(m).match(/^GW(\d+)\s·\s(.*)$/);
        const gw = mm ? mm[1] : '';
         
         
         
         
        const body = (mm ? mm[2] : String(m)).split(PLAN_WHY_MARK)[0];
        const parts = body.split(' → ');
        const mv = (parts.length === 2)
          ? `<span style="color:var(--muted);text-decoration:line-through;">${parts[0]}</span>`
            + ` <span style="color:#17774E;">→</span> <span style="font-weight:700;color:#17774E;">${parts[1]}</span>`
          : `<span style="font-weight:700;color:#6d28d9;">${body}</span>`;
        h += `<span style="white-space:nowrap;">${gw ? `<b style="color:var(--muted);">GW${gw}</b> ` : ''}${mv}</span>`;
      }
      if (more > 0) h += `<span style="color:var(--muted);">+${more} more</span>`;
      h += `<span style="margin-left:auto;color:var(--accent,#17774E);font-weight:800;">open the tree →</span>`;
      el.innerHTML = h;
      el.style.display = 'flex';
      return true;
    }
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
     
