function apexMinutesProbs(xm, pos) {
  var x = Math.max(0, Math.min(+xm || 0, 90));
  var K = (typeof MINUTES_PROBS_KNOTS !== 'undefined' && MINUTES_PROBS_KNOTS) ? MINUTES_PROBS_KNOTS : null;
  var pAny, p60;
  var _posKey = (pos == null || !isFinite(+pos)) ? null : String(Math.trunc(+pos));
  if (K && K.knots && K.knots.length && K.p_any && K.p_60) {
    var _bp = (_posKey && K.by_pos && K.by_pos[_posKey]) ? K.by_pos[_posKey] : null;
    var _pa = (_bp && _bp.p_any) ? _bp.p_any : K.p_any;
    var _p6 = (_bp && _bp.p_60) ? _bp.p_60 : K.p_60;
    var at = function (vals) {
      var kn = K.knots;
      for (var i = 1; i < kn.length; i++) {
        if (x <= kn[i]) {
          var x0 = kn[i - 1], x1 = kn[i];
          if (x1 <= x0) return vals[i];
          return vals[i - 1] + (vals[i] - vals[i - 1]) * ((x - x0) / (x1 - x0));
        }
      }
      return vals[vals.length - 1];
    };
    pAny = at(_pa); p60 = at(_p6);
    var cap = K.cap && +K.cap.min_cameo_minutes;
    if (cap > 0) {
      var firstKnot = null;
      for (var j = 0; j < K.knots.length; j++) { if (K.knots[j] > 0) { firstKnot = K.knots[j]; break; } }
      if (firstKnot != null && x < firstKnot) {
        pAny = Math.min(pAny, x / cap);
        p60 = Math.min(p60, x / 60);
      }
    }
  } else {
    pAny = x / 90;
    p60 = Math.min(Math.max(0, (x - 30) / 60), pAny);
  }
  var _gk = K && +K.gk_start_minutes;
  if (_posKey === '1' && _gk > 0) {
    pAny = Math.min(pAny, x / _gk);
    p60 = Math.min(p60, pAny);
  }
  return { pAny: pAny, p60: p60 };
}
 
 
 
 
 
 
 

 
 
 
 
 
 
 
 
 
 
 
 
 
