let _poolRemovedPlayer = null;    
 
 
 
 
 
 
 
 
let _poolDropped = [];

 
 
 
 
 
 
 
 
 
 
 
 
 
function _poolAvailableCash() {
  if (!(typeof window !== 'undefined' && window._lastChipSquad) && typeof _apexLedgerBankAt === 'function') {
    return Math.round(_apexLedgerBankAt((typeof activeGwIdx === 'number') ? activeGwIdx : 0) * 10) / 10;
  }
  const cap = TEAM_META.budget || ((TEAM_META.squad_value || 0) + (TEAM_META.bank || 0));
  const used = [..._xiPlayers, ..._benchPlayers].reduce((t, p) => t + ((typeof _apexSellPrice === 'function') ? _apexSellPrice(p) : (p.cost || 0)), 0);
  return Math.round((cap - used) * 10) / 10;
}
let _poolRemovedFromXi = true;    
 
 
 
 
 
let _poolOriginalRemoved = null;
let _poolOriginalFromXi  = true;
